"""
ALL-IN-ONE MASTER IMPLEMENTATION & SYNC SCRIPT FOR 60th MNSS TRANSPORT SYSTEM
==============================================================================
Applies all discussed portals, backend APIs, Excel bulk uploaders, helpline subdomain,
date-wise rosters, nearby-vicinity allocation, driver park-empty loop, and station pickup guides
into `C:\narendra\SamagamtransportV1` in a single run.

Usage (in PowerShell inside C:\narendra\SamagamtransportV1):
    python deploy_all_samagam_updates_fixed.py
"""
import os
import re

BASE_DIR = os.path.dirname(os.path.abspath(__file__))


def read_file(path):
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        return f.read()


def write_file(path, text):
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)


def sync_html_to_root(filename, html_content):
    write_file(os.path.join(BASE_DIR, filename), html_content)
    root_dir = os.path.join(BASE_DIR, "root")
    if os.path.isdir(root_dir):
        write_file(os.path.join(root_dir, filename), html_content)

