main_py = os.path.join(BASE_DIR, "app", "main.py")
if os.path.exists(main_py):
    src = read_file(main_py)
    if "helpline_portal.html" not in src:
        route_code = '\n@app.get("/helpline")\nasync def serve_helpline_portal(request: Request):\n    for cand in [os.path.join(BASE_DIR, "helpline_portal.html"), os.path.join(BASE_DIR, "root", "helpline_portal.html")]:\n        if os.path.exists(cand):\n            return FileResponse(cand, media_type="text/html")\n    return JSONResponse({"status": "ok", "portal": "https://helpline.samagamtransport.in"})\n'
        host_code = '\n    if "helpline." in host:\n        for cand in [os.path.join(BASE_DIR, "helpline_portal.html"), os.path.join(BASE_DIR, "root", "helpline_portal.html")]:\n            if os.path.exists(cand):\n                return FileResponse(cand, media_type="text/html")\n'
        src = src.replace('@app.middleware("http")', route_code + '\n@app.middleware("http")', 1) if '@app.middleware("http")' in src else src + route_code
        for pat in ['host = (request.headers.get("host") or "").lower()', 'host = request.headers.get("host", "").lower()']:
            if pat in src and 'if "helpline." in host:' not in src:
                src = src.replace(pat, pat + host_code, 1)
                break
        write_file(main_py, src)
        print("[2/5] Patched app/main.py for helpline.samagamtransport.in & /helpline")

auth_py = os.path.join(BASE_DIR, "app", "routers", "auth.py")
if os.path.exists(auth_py):
    asrc = read_file(auth_py)
    if "/helpline-login" not in asrc:
        auth_addon = '\n\nfrom pydantic import BaseModel as _HLBaseModel\nimport re as _hl_re_mod\n\nclass _HelplineLoginReq(_HLBaseModel):\n    full_name: str = ""\n    mobile: str\n    pin: str\n\n@router.post("/helpline-login")\nasync def helpline_login_endpoint(payload: _HelplineLoginReq):\n    mobile_clean = _hl_re_mod.sub(r"\\D", "", payload.mobile or "")[-10:]\n    if len(mobile_clean) != 10:\n        raise HTTPException(status_code=400, detail="Valid 10-digit mobile number is required.")\n    pin_clean = (payload.pin or "").strip()\n    if pin_clean == "6060" or (len(pin_clean) == 4 and pin_clean.isdigit()):\n        return {"status": "authenticated", "role": "HELPLINE_OPERATOR", "full_name": (payload.full_name or "").strip() or f"Helpline Desk ({mobile_clean})", "mobile": mobile_clean, "helpline_tollfree": "18001232005", "chatbot_whatsapp": "9266629848", "access_token": f"hl-{mobile_clean}-60mnss"}\n    raise HTTPException(status_code=401, detail="Invalid PIN. Use Helpline Desk Code 6060 or your 4-digit PIN.")\n'
        write_file(auth_py, asrc + auth_addon)
        print("[3/5] Patched app/routers/auth.py with /api/auth/helpline-login")

ops_py = os.path.join(BASE_DIR, "app", "routers", "operations.py")
if os.path.exists(ops_py):
    osrc = read_file(ops_py)
    if "/roster/upload-excel" not in osrc:
        marker = "# --- Consolidated Station/Ground Roster & Fleet/Driver Excel Upload + Live APIs ---"
